<?php
namespace App\Filters;
use App\Models\CustomerModel;
use CodeIgniter\Filters\FilterInterface; use CodeIgniter\HTTP\RequestInterface; use CodeIgniter\HTTP\ResponseInterface;
class CustomerAuth implements FilterInterface { public function before(RequestInterface $request, $arguments = null) { $customer = session('customer_logged_in') ? (new CustomerModel())->find(session('customer_id')) : $this->fromRememberCookie($request); if (!$customer || $customer['status'] !== 'active') { session()->remove(['customer_id','customer_name','customer_logged_in']); return redirect()->to(route_to('customer.login'))->with('warning', 'Please log in to continue.'); } } private function fromRememberCookie(RequestInterface $request): ?array { $cookie=$request->getCookie('taharat_remember'); if(!$cookie || !str_contains($cookie,'.'))return null; [$id,$token]=explode('.',$cookie,2); if(!ctype_digit($id) || strlen($token)!==64)return null; $customer=(new CustomerModel())->find((int)$id); if(!$customer || !$customer['remember_token'] || !hash_equals($customer['remember_token'],hash('sha256',$token)))return null; session()->regenerate(true); session()->set(['customer_id'=>$customer['id'],'customer_name'=>$customer['full_name'],'customer_logged_in'=>true]); return $customer; } public function after(RequestInterface $request, ResponseInterface $response, $arguments = null) {} }
